namespace BlazorApp.Services;

public class NotificationItem
{
    public int Id { get; set; }
    public string Message { get; set; } = "";
    public DateTime Timestamp { get; set; }
}

public class NotificationService
{
    private int _nextId = 1;
    private readonly List<NotificationItem> _notifications = new();
    private readonly Lock _lock = new();

    public NotificationService()
    {
        // Seed with initial fake data.
        _notifications.AddRange(new[]
        {
            new NotificationItem { Id = _nextId++, Message = "Welcome to the app!", Timestamp = DateTime.UtcNow.AddMinutes(-30) },
            new NotificationItem { Id = _nextId++, Message = "Your profile was updated.", Timestamp = DateTime.UtcNow.AddMinutes(-15) },
            new NotificationItem { Id = _nextId++, Message = "New feature available: dark mode.", Timestamp = DateTime.UtcNow.AddMinutes(-5) },
        });
    }

    /// <summary>Returns all notifications.</summary>
    public List<NotificationItem> GetAll()
    {
        lock (_lock)
        {
            return _notifications.OrderByDescending(n => n.Timestamp).ToList();
        }
    }

    /// <summary>Returns notifications created after the given timestamp.</summary>
    public List<NotificationItem> GetSince(DateTime since)
    {
        lock (_lock)
        {
            return _notifications
                .Where(n => n.Timestamp > since)
                .OrderByDescending(n => n.Timestamp)
                .ToList();
        }
    }

    /// <summary>Simulates a new notification arriving roughly every 10–20 seconds.</summary>
    public void SimulateIncoming()
    {
        lock (_lock)
        {
            if (Random.Shared.Next(0, 3) == 0) // ~1-in-3 chance per poll
            {
                _notifications.Add(new NotificationItem
                {
                    Id = _nextId++,
                    Message = $"Something happened (event #{_nextId - 1}).",
                    Timestamp = DateTime.UtcNow,
                });
            }
        }
    }
}

@page "/notifications"
@rendermode InteractiveServer
@implements IDisposable
@inject BlazorApp.Services.NotificationService NotificationSvc

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    @if (Items is not null)
    {
        <span class="badge bg-primary rounded-pill ms-2">@Items.Count</span>
    }
</h1>

@if (Items is null)
{
    <p><em>Loading…</em></p>
}
else if (Items.Count == 0)
{
    <p>No notifications.</p>
}
else
{
    <ul class="list-group">
        @foreach (var n in Items)
        {
            <li class="list-group-item d-flex justify-content-between align-items-start">
                <span>@n.Message</span>
                <small class="text-muted">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    [PersistentState]
    public List<BlazorApp.Services.NotificationItem>? Items { get; set; }

    private CancellationTokenSource? _cts;

    protected override void OnInitialized()
    {
        // Only load when state wasn't restored from prerender.
        Items ??= NotificationSvc.GetAll();
    }

    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            // This only fires in the interactive runtime, never during prerender.
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(5), ct).ConfigureAwait(false);

            NotificationSvc.SimulateIncoming();
            var latest = NotificationSvc.GetAll();

            await InvokeAsync(() =>
            {
                Items = latest;
                StateHasChanged();
            });
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

